<form class="tm-card tm-crm-form" method="get" action="/tickets/crm" data-ticket-form><label for="crm-id">Exact CRM ID<input id="crm-id" type="search" name="crm_id" maxlength="120" value="<?= e($crmId) ?>" placeholder="Enter the full CRM ID" required></label><button class="tm-button tm-primary" type="submit">Search customer</button></form>
<?php if (!$customer): ?><section class="tm-card tm-empty"><span aria-hidden="true">⌕</span><h2><?= $crmId!==''?'No customer found':'Find a customer record' ?></h2><p><?= $crmId!==''?'No customer matches this exact CRM ID. Check the ID and try again.':'Enter an exact CRM ID to see customer details, linked tickets and conversation summaries.' ?></p></section>
<?php else: ?>
<div class="tm-grid">
  <section class="tm-card tm-wide"><div class="tm-card-heading tm-teal"><h2>Customer / CRM <?= e($customer['crm_id']) ?></h2><span>Customer mirror</span></div><div class="tm-card-body"><?php ticket_facts(['Customer name'=>$customer['applicant_name'],'ID number (masked)'=>$customer['nric'],'Email'=>$customer['email'],'Phone'=>$customer['phone'],'Classification'=>ticket_label($customer['customer_type']),'State'=>$customer['state'],'Language'=>$customer['language'],'Company name'=>$customer['company_name'],'Company number'=>$customer['company_no'],'Interaction status'=>$customer['current_status'],'CLOG source status'=>$customer['clog_status'],'RPA outcome code'=>$customer['rpa_outcome_code'],'Completed'=>ticket_date($customer['completed_at'])]); ?><p class="tm-note">The CRM/customer record is separate from its operational tickets. Statuses shown here describe the customer mirror.</p></div></section>
  <section class="tm-card tm-wide"><div class="tm-card-heading"><h2>Linked tickets</h2><span><?= count($customer['tickets']) ?> tickets</span></div><div class="tm-card-body"><?php if (!$customer['tickets']): ?><p class="tm-empty-inline">No tickets are linked to this customer.</p><?php endif; ?><?php foreach ($customer['tickets'] as $linked): ?><article class="tm-linked-ticket"><div><a href="/tickets/<?= e($linked['id']) ?>"><?= e($linked['id']) ?> ↗</a><span class="tm-subtext"><?= e($linked['scenario_key'] ?: 'No scenario') ?> · <?= e(strtoupper($linked['source_type'])) ?></span><span class="tm-subtext">Updated <?= e(ticket_date($linked['updated_at'])) ?></span></div><span class="tm-badge tm-<?= e($linked['workflow_status']) ?>"><?= e(ticket_label($linked['workflow_status'])) ?></span></article><?php endforeach; ?></div></section>
  <section class="tm-card"><div class="tm-card-heading"><h2>Email thread summaries</h2><span><?= count($customer['email_threads']) ?> threads</span></div><div class="tm-card-body"><p class="tm-note">Open a linked ticket’s Conversation tab to read its messages. CRM grouping does not prove a reply chain.</p><?php if (!$customer['email_threads']): ?><p class="tm-empty-inline">No conversation threads linked.</p><?php endif; ?><?php foreach ($customer['email_threads'] as $thread): ?><article class="tm-message"><h3><?= e($thread['subject'] ?: 'No subject') ?></h3><?php ticket_facts(['Thread UUID'=>$thread['id'],'Message count'=>$thread['message_count'],'First message'=>ticket_date($thread['first_message_at']),'Last message'=>ticket_date($thread['last_message_at'])]); ?></article><?php endforeach; ?></div></section>
  <section class="tm-card"><div class="tm-card-heading tm-amber"><h2>CLOG source records</h2><span><?= count($customer['clog_records']) ?> records</span></div><div class="tm-card-body"><?php if (!$customer['clog_records']): ?><p class="tm-empty-inline">No source-detail summaries available.</p><?php endif; ?><?php foreach ($customer['clog_records'] as $record): ?><article class="tm-message"><h3><?= e($record['form_name'] ?: 'Source record') ?></h3><?php ticket_facts(['Source record ID'=>$record['source_data_id'],'Parent record ID'=>$record['parent_id'],'Form ID'=>$record['form_id'],'Customer type'=>$record['customer_type'],'Interaction type'=>$record['interaction_type'],'Language'=>$record['language'],'State / location'=>$record['state_location'],'Contact ID'=>$record['contact_id'],'Source time'=>ticket_date($record['source_created_at'])]); ?></article><?php endforeach; ?></div></section>
</div>
<?php endif; ?>
